from enum import Enum

class LogLevel(Enum):
    DEBUG = 10
    INFO = 20
    WARN = 30
    ERROR = 40

    def __str__(self):
        return f'LOG: {self.name}'

    @classmethod
    def from_priority(cls, priority):
        best = None
        best_diff = float('inf')
        for level in cls:
            diff = abs(level.value - priority)
            if diff < best_diff:
                best_diff = diff
                best = level
        return best

def load_default_level(config_str):
    try:
        return LogLevel[config_str.upper()]
    except KeyError:
        return LogLevel.INFO

