from enum import Enum, auto

class Permission(Enum):
    READ = auto()
    WRITE = auto()
    DELETE = auto()

    def has_permission(self, other):
        return self.value >= other.value

user_permissions = {
    'alice': Permission.WRITE,
    'bob': Permission.READ,
    'carol': Permission.DELETE
}

def check_access(user, required):
    if user not in user_permissions:
        return False
    return user_permissions[user].has_permission(required)
